  rw_cells asegs m X (SvcHdrCells (mkSVC vp ti id owner nx dsv)) ->
  addressable m X nX -> 48 <= nX -> 0 < X -> X + nX <= aceil -> X mod 16 = 0 -> 0 <= nx < 2^64 -> 0 <= dsv < 2^64 -> dsv mod 2 = 0 ->
  (X + 48 <= regb + 48 \/ regb + 64 <= X) ->
