             (Z_to_bv 64 (regb + 56)) (Z_to_bv 64 (Z.shiftr (regb + 56) 3 + 2147450880)) (Z_to_bv 64 X) s8 s9 (Z_to_bv 64 2147450880) s11 t3 t4 t5 t6)
